#include "rigid.hpp"
#include <fstream>
#include <iomanip>
#include <iostream>
#include <filesystem>
#include <chrono>
#include <sstream>
#include <omp.h>
using namespace rigid;
struct Reference {std::vector<State>state;double gap=0,drift=0;bool certified=true;int sub=0;};
Reference reference(const Case&c,double h,int steps){Reference r;Scale q=scales(c.model,c.initial);V a=angles(c.model,c.initial),b=a;double initial=energy(c.model,c.initial);r.state.push_back(c.initial);r.sub=std::max(32,int(std::ceil(std::abs(h)*3840)));for(int j=0;j<steps;++j){a=rk4(c.model,a,h,r.sub);b=rk4(c.model,b,h,2*r.sub);State sa=cartesian(c.model,a),sb=cartesian(c.model,b);if(!finite(sa)||!finite(sb)){r.certified=false;break;}r.state.push_back(sb);r.gap=std::max(r.gap,(encode(sa,q)-encode(sb,q)).norm());r.drift=std::max(r.drift,std::abs(energy(c.model,sb)-initial)/q.e);}r.certified=r.certified&&r.gap<1e-5&&r.drift<1e-7;return r;}
void require(bool b,const std::string&s){if(!b)throw std::runtime_error(s);}
void validate(){double maxacc=0,maxham=0,maxinv=0,maxrev=0,maxenergy=0,maxhdiff=0;for(const auto&c:cases()){const Model&m=c.model;int n=m.count;Scale q=scales(m,c.initial);V z=angles(m,c.initial),dz=angle_ode(m,z),ac=V::Zero(2*n);Eigen::Vector2d cumulative=Eigen::Vector2d::Zero();for(int j=0;j<n;++j){double a=z[j],w=z[n+j],aa=dz[n+j],l=m.length[j];cumulative+=l*(-w*w*Eigen::Vector2d(std::sin(a),-std::cos(a))+aa*Eigen::Vector2d(std::cos(a),std::sin(a)));ac.segment<2>(2*j)=cumulative;}maxacc=std::max(maxacc,(ac-acceleration(m,c.initial)).norm()/(1+ac.norm()));require(maxacc<1e-10,"independent_angle_cartesian_acceleration");
 V can=canonical(m,c.initial,q),gh=hamiltonian_gradient(m,can,q),fd=gh;for(int k=0;k<can.size();++k){V a=can,b=can;a[k]+=1e-6;b[k]-=1e-6;fd[k]=(hamiltonian(m,a,q)-hamiltonian(m,b,q))/(2e-6);}maxham=std::max(maxham,(gh-fd).norm()/(1+gh.norm()));require(maxham<1e-7,"hamiltonian_gradient");for(double eps:{.01,.0001,1e-8}){V zz=can;for(int k=0;k<zz.size();++k)zz[k]+=eps*std::sin(k+1);double direct=hamiltonian(m,zz,q)-hamiltonian(m,can,q),stable=hamiltonian_difference(m,can,zz,q);maxhdiff=std::max(maxhdiff,std::abs(direct-stable));require(maxhdiff<1e-10,"stable_hamiltonian_difference");}
 V y=encode(c.initial,q);y[0]+=.03;y[y.size()/2]+=.04;Mat g=inv_gradient(m,y,q,true,true),gfd=g;for(int k=0;k<y.size();++k){V a=y,b=y;a[k]+=1e-6;b[k]-=1e-6;gfd.col(k)=(invariants(m,a,q,0,true,true)-invariants(m,b,q,0,true,true))/(2e-6);}maxinv=std::max(maxinv,(g-gfd).norm()/(1+g.norm()));require(maxinv<1e-7,"invariant_gradient");
 for(std::string meth:{"rattle","cart_dg","sym_energy","sym_geom","canonical_dg","canonical_midpoint","post_energy","rattle_energy"}){Result a=raw(m,c.initial,1./240,q,meth);require(a.ok,"step_"+c.name+"_"+meth+"_"+a.reason);double en=std::abs(energy(m,a.s)-energy(m,c.initial))/q.e;require(constraints(m,a.s.x).norm()<1e-7,"length_"+meth);if(meth!="cart_dg")require((gradient(m,a.s.x)*a.s.v).norm()/q.v<1e-7,"tangency_"+meth);if(meth.find("energy")!=std::string::npos||meth.find("_dg")!=std::string::npos){maxenergy=std::max(maxenergy,en);require(en<1e-7,"energy_"+meth);}if(meth!="post_energy"&&meth!="rattle_energy"){Result b=raw(m,a.s,-1./240,q,meth);require(b.ok,"reverse_"+meth);double err=(encode(b.s,q)-encode(c.initial,q)).norm();maxrev=std::max(maxrev,err);require(err<1e-7,"reversal_"+meth);}}
 if(!has_gravity(m)){for(std::string method:{"canonical_dg_momentum","canonical_avf_momentum","canonical_dg_momentum_stable","canonical_avf_momentum_stable","sym_energy_momentum"}){Result a=raw(m,c.initial,.03,q,method),b=raw(m,a.s,-.03,q,method);require(a.ok&&b.ok,"momentum_variant_convergence");require(std::abs(angular(m,a.s)-angular(m,c.initial))<1e-8,"momentum_variant_invariant");require(std::abs(energy(m,a.s)-energy(m,c.initial))/q.e<1e-8,"momentum_variant_energy");require((encode(c.initial,q)-encode(b.s,q)).norm()<1e-7,"momentum_variant_reversal");}}
 }
 std::cout<<std::setprecision(16)<<"validation acceleration="<<maxacc<<" Hamiltonian_gradient="<<maxham<<" invariant_gradient="<<maxinv<<" reversal="<<maxrev<<" energy="<<maxenergy<<" stable_H_difference="<<maxhdiff<<std::endl;
}
std::string run(const Case&c,const Reference&ref,double h,double duration,const std::string&method,const std::string&folder,bool traces){const Model&m=c.model;Scale q=scales(m,c.initial);State s=c.initial;double e0=energy(m,s),L0=angular(m,s),sumx=0,sumv=0,maxE=0,maxC=0,maxT=0,maxRev=0,maxL=0,maxRes=0,maxK=0;int N=std::lround(duration/h),done=0,matched=0,it=0,ev=0,leaves=0,reject=0,revfails=0;std::string status="complete",reason;std::ofstream tr;if(traces){tr.open(folder+"/trace_"+c.name+"_"+method+"_"+std::to_string(h)+".csv");tr<<std::setprecision(16)<<"t,energy,tangency,length";for(int j=0;j<2*m.count;++j)tr<<",x"<<j;for(int j=0;j<2*m.count;++j)tr<<",v"<<j;for(int j=0;j<2*m.count;++j)tr<<",ref_x"<<j;tr<<"\n";}
 auto tic=std::chrono::steady_clock::now();for(int k=0;k<N;++k){State old=s;Result a=advance(m,old,h,q,method);it+=a.iterations;ev+=a.evaluations;leaves+=a.leaves;reject+=a.rejections;if(!a.ok){status="failed";reason=a.reason;break;}s=a.s;++done;maxRes=std::max(maxRes,a.residual);double ee=std::abs(energy(m,s)-e0)/q.e,cc=constraints(m,s.x).norm()/(q.l*q.l),tt=(gradient(m,s.x)*s.v).norm()/(q.l*q.v);maxE=std::max(maxE,ee);maxC=std::max(maxC,cc);maxT=std::max(maxT,tt);maxL=std::max(maxL,std::abs(angular(m,s)-L0)/(m.mass.sum()*q.l*q.v));maxK=std::max(maxK,((s.x-old.x)/h-.5*(old.v+s.v)).norm()/q.v);if(k<8){Result b=advance(m,s,-h,q,method);if(b.ok)maxRev=std::max(maxRev,(encode(b.s,q)-encode(old,q)).norm());else ++revfails;}if(k+1<int(ref.state.size())){sumx+=(s.x-ref.state[k+1].x).squaredNorm()/m.count;sumv+=(s.v-ref.state[k+1].v).squaredNorm()/m.count;++matched;}if(traces){tr<<(k+1)*h<<","<<energy(m,s)<<","<<tt<<","<<cc;for(double a:s.x)tr<<","<<a;for(double a:s.v)tr<<","<<a;for(double a:ref.state[std::min(k+1,int(ref.state.size())-1)].x)tr<<","<<a;tr<<"\n";}if(ee>1e6||s.x.norm()>1e6){status="runaway";reason="energy_or_state_limit";break;}}
 double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-tic).count();std::ostringstream o;o<<std::setprecision(16)<<c.name<<","<<m.count<<","<<method<<","<<h<<","<<duration<<","<<status<<","<<reason<<","<<done<<","<<N<<","<<ref.certified<<","<<ref.sub<<","<<ref.gap<<","<<ref.drift<<","<<(matched?std::sqrt(sumx/matched):std::numeric_limits<double>::quiet_NaN())<<","<<(matched?std::sqrt(sumv/matched):std::numeric_limits<double>::quiet_NaN())<<","<<maxE<<","<<maxC<<","<<maxT<<","<<maxK<<","<<maxL<<","<<maxRev<<","<<revfails<<","<<maxRes<<","<<it<<","<<ev<<","<<reject<<","<<leaves<<","<<ms;return o.str();}
int main(int argc,char**argv){try{validate();std::string mode=argc>1?argv[1]:"short",folder=argc>2?argv[2]:"results";if(mode=="validate")return 0;std::filesystem::create_directories(folder);auto cs=cases();std::vector<double>hs={1./120,1./30};double duration=10;std::vector<std::string>methods={"rattle","cart_dg","sym_geom","sym_energy","post_energy","rattle_energy","canonical_midpoint","canonical_dg"};if(mode=="long"){duration=60;hs={1./60};methods={"rattle","cart_dg","sym_energy","canonical_dg","canonical_midpoint"};cs.erase(std::remove_if(cs.begin(),cs.end(),[](const Case&c){return c.name!="double_small"&&c.name!="triple_small"&&c.name!="double_moderate"&&c.name!="triple_moderate";}),cs.end());}if(mode=="accuracy"){duration=10;hs={1./30};methods={"rattle_accuracy","sym_energy_accuracy","canonical_dg_accuracy","cart_dg_accuracy"};}if(mode=="stress"){duration=2;hs={.1,.25};methods={"rattle","cart_dg","sym_energy","canonical_dg","rattle_accuracy","sym_energy_accuracy","canonical_dg_accuracy"};}if(mode=="order"){duration=1;hs={1./30,1./60,1./120,1./240};cs.erase(std::remove_if(cs.begin(),cs.end(),[](const Case&c){return c.name!="double_moderate"&&c.name!="triple_moderate";}),cs.end());}
 if(mode=="momentum"||mode=="momentum_long"||mode=="momentum_stable"){cs={make("double_free",vec({.3,-.2}),vec({4,-2}),vec({1,2}),0),make("triple_free",vec({.3,-.2,.4}),vec({3,-2,1}),vec({1,1,1}),0),make("double_free_contrast",vec({.3,-.2}),vec({4,-2}),vec({1,20}),0)};hs={1./120,1./30};duration=mode=="momentum_long"?60:10;methods={"rattle","cart_dg","canonical_midpoint","canonical_dg","canonical_dg_momentum","canonical_avf_momentum","sym_energy","sym_energy_momentum","post_energy_momentum"};if(mode=="momentum_stable")methods={"canonical_dg_momentum_stable","canonical_avf_momentum_stable"};}
 if(mode=="metric"){cs.erase(std::remove_if(cs.begin(),cs.end(),[](const Case&c){return c.name!="double_moderate"&&c.name!="triple_moderate"&&c.name!="double_free"&&c.name!="double_fast";}),cs.end());hs={1./60,1./30};methods={"canonical_dg","canonical_dg_p01","canonical_dg_p10","canonical_avf","canonical_avf_p01","canonical_avf_p10","canonical_midpoint"};}
 if(mode=="objectives"||mode=="objectives_order"){cs.erase(std::remove_if(cs.begin(),cs.end(),[](const Case&c){return c.name!="double_moderate"&&c.name!="triple_moderate"&&c.name!="double_free"&&c.name!="double_light_tip";}),cs.end());methods={"obj_original_midpoint_b1","obj_quarter_b1","obj_midpotential_b1","obj_ls_dg_E","obj_ls_dg","obj_projection_verlet_E","obj_projection_verlet_EL"};if(mode=="objectives_order"){duration=1;hs={1./30,1./60,1./120,1./240};}}
 if(mode=="reaction_order"){cs.erase(std::remove_if(cs.begin(),cs.end(),[](const Case&c){return c.name!="double_moderate"&&c.name!="triple_moderate";}),cs.end());methods.clear();for(double c:{0.,.5,1.,1.5,2.})for(double b:{.1,1.,10.})methods.push_back("obj_reaction"+std::to_string(c)+"_b"+std::to_string(b));duration=1;hs={1./30,1./60,1./120,1./240};}
 if(mode=="equilibria"||mode=="equilibria_stable"){cs.clear();for(int n:{2,3})for(int power:{0,8,6,4,2}){double amp=power?std::pow(10.,-power):0;V a=V::Constant(n,.3);for(int j=0;j<n;++j)a[j]+=(j%2?amp:-amp);cs.push_back(make("free_equilibrium_"+std::to_string(n)+"_p"+std::to_string(power),a,V::Constant(n,4),V::Ones(n),0));}methods={"rattle","cart_dg","canonical_midpoint","canonical_dg","canonical_dg_momentum","canonical_avf_momentum","sym_energy_momentum","obj_projection_verlet_EL"};hs={1./30,.1};duration=10;if(mode=="equilibria_stable")methods={"canonical_dg_momentum_stable","canonical_avf_momentum_stable"};}
 struct Batch{Case c;double h;};std::vector<Batch>bs;for(auto&c:cs)for(double h:hs)bs.push_back({c,h});std::vector<std::string>rows(bs.size());
 #pragma omp parallel for schedule(dynamic)
 for(int j=0;j<int(bs.size());++j){auto&b=bs[j];Reference ref=reference(b.c,b.h,std::lround(duration/b.h));std::ostringstream o;for(auto&method:methods)o<<run(b.c,ref,b.h,duration,method,folder,(b.h==1./30||mode=="long")&&mode!="accuracy")<<"\n";rows[j]=o.str();
 #pragma omp critical
 std::cout<<"completed "<<j+1<<"/"<<bs.size()<<" "<<b.c.name<<" h="<<b.h<<" reference="<<ref.certified<<" gap="<<ref.gap<<std::endl;
 }
 std::ofstream f(folder+"/summary.csv");f<<"case,links,method,h,duration,status,reason,steps_done,steps_requested,reference_certified,reference_substeps,reference_gap,reference_energy_drift,position_rms,velocity_rms,max_energy_relative,max_geometry,max_tangency,max_midpoint_defect,max_angular_change,max_local_reversal,reversal_failures,max_solver_residual,newton_iterations,residual_evaluations,rejected_attempts,accepted_substeps,wall_ms\n";for(auto&r:rows)f<<r;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
